<template><div v-if="text" class="rich-content"><template v-for="(part,i) in parts" :key="i"><img v-if="part.type==='emoji'" :src="assetUrl(part.value)" :alt="part.value" class="rich-content-emoji"><div v-else-if="part.type==='img'" class="rich-content-attached-image"><img :src="part.value" alt="embedded"></div><template v-else><span v-for="(line,j) in part.value.split('\n')" :key="`${i}-${j}`">{{j?'\n':''}}{{line}}</span></template></template></div></template>
<script setup>import {computed} from 'vue';const assetUrl=(file)=>`/assets/images/imgs/${encodeURIComponent(file)}`;const props=defineProps({text:{type:String,default:''}});const parts=computed(()=>props.text.split(/(\[emoji:[^\]]+\]|\[img:[^\]]+\])/g).filter(Boolean).map(x=>{let m=x.match(/^\[emoji:(.+)\]$/);if(m)return{type:'emoji',value:m[1]};m=x.match(/^\[img:(.+)\]$/);if(m)return{type:'img',value:m[1]};return{type:'text',value:x}}));</script>
<style scoped>.rich-content-emoji{display:inline-block;width:80px;height:80px;object-fit:cover;vertical-align:middle;margin:0 4px;border-radius:4px}.rich-content-attached-image{margin:16px 0}.rich-content-attached-image img{display:block;max-width:100%;max-height:400px;border-radius:8px;object-fit:contain}</style>
